// Clasificar hallazgos del payload — 19 herramientas REGINSA
const data = $input.first().json;

const niveles = { CRITICA: 0, CRITICO: 0, ALTA: 1, ALTO: 1, MEDIA: 2, MEDIO: 2, BAJA: 3, BAJO: 3, INFO: 4 };

const resumen  = data.resumen || {};
const findings = (data.top_hallazgos || []).map(f => ({
  severidad:   f.severidad   || 'INFO',
  herramienta: f.herramienta || 'N/A',
  hallazgo:    f.hallazgo    || '',
  componente:  f.componente  || '',
  categoria:   f.tipo_prueba || 'General'
}));

const maxNivel = findings.reduce((min, f) => {
  const n = niveles[f.severidad.toUpperCase()] ?? 4;
  return n < min ? n : min;
}, 4);

const nivelTexto = maxNivel === 0 ? 'CRITICO' : maxNivel === 1 ? 'ALTO' : maxNivel === 2 ? 'MEDIO' : 'BAJO';
const color = maxNivel === 0 ? 'attention' : maxNivel === 1 ? 'warning' : 'good';
const emoji = maxNivel === 0 ? '🚨' : maxNivel === 1 ? '⚠️' : '✅';

// Tabla top 10 hallazgos
const filas = findings.slice(0, 10).map(f =>
  `${f.severidad.padEnd(8)} | ${f.herramienta.padEnd(15)} | ${f.hallazgo.substring(0, 70)}`
).join('\n');

// Resumen por categoria de herramientas
const herramientas = data.herramientas || [];
const cats = { sast: [], sca: [], dast: [], container: [], infra: [], network: [], 'code-quality': [] };
for (const h of herramientas) {
  const cat = (h.categoria || 'otro').toLowerCase();
  if (cats[cat]) cats[cat].push(h);
}
const iconH = s => s === 'PASS' ? '✅' : s === 'WARN' ? '⚠️' : s === 'SKIP' ? '⏭️' : '❌';
const fmtCat = (label, arr) => arr.length ?
  `**${label}**: ` + arr.map(h => `${iconH(h.estado)} ${h.herramienta.split('(')[0].trim()} (${h.duracion||'-'})`).join(', ') : '';

const resumenCats = [
  fmtCat('SAST',          cats['sast']),
  fmtCat('SCA',           cats['sca']),
  fmtCat('Container',     cats['container']),
  fmtCat('DAST',          cats['dast']),
  fmtCat('Infra',         cats['infra']),
  fmtCat('Network',       cats['network']),
  fmtCat('Code Quality',  cats['code-quality']),
].filter(Boolean).join('\n');

// Conteo PASS/WARN/SKIP
const totPass = herramientas.filter(h => h.estado === 'PASS').length;
const totWarn = herramientas.filter(h => h.estado === 'WARN').length;
const totSkip = herramientas.filter(h => h.estado === 'SKIP').length;

return [{
  json: {
    ...data,
    _meta: {
      dispararAlerta:      data.disparar === true,
      nivelMaximo:         nivelTexto,
      color:               color,
      emoji:               emoji,
      totalCritico:        resumen.critico || 0,
      totalAlto:           resumen.alto    || 0,
      totalMedio:          resumen.medio   || 0,
      totalGeneral:        resumen.total   || 0,
      tablaHallazgos:      filas,
      resumenCategorias:   resumenCats,
      herramientasPASS:    totPass,
      herramientasWARN:    totWarn,
      herramientasSKIP:    totSkip,
      dojoUrl:             data.defectdojo ? data.defectdojo.url : null
    }
  }
}];

