={
  "@type": "MessageCard",
  "@context": "http://schema.org/extensions",
  "themeColor": "{{ $json._meta.color === 'attention' ? 'FF0000' : $json._meta.color === 'warning' ? 'FFA500' : '00AA00' }}",
  "summary": "{{ $json._meta.emoji }} REGINSA Security Alert - {{ $json.fecha }}",
  "sections": [
    {
      "activityTitle": "{{ $json._meta.emoji }} Alerta Seguridad REGINSA — {{ $json._meta.nivelMaximo }}",
      "activitySubtitle": "{{ $json.fecha }} | Proyecto: SI091-REGINSA (SUNEDU)",
      "facts": [
        { "name": "Total hallazgos", "value": "{{ $json._meta.totalGeneral }}" },
        { "name": "Critico",         "value": "{{ $json._meta.totalCritico }}" },
        { "name": "Alto",            "value": "{{ $json._meta.totalAlto }}" },
        { "name": "Medio",           "value": "{{ $json._meta.totalMedio }}" },
        { "name": "Herramientas",    "value": "✅ {{ $json._meta.herramientasPASS }} PASS | ⚠️ {{ $json._meta.herramientasWARN }} WARN | ⏭️ {{ $json._meta.herramientasSKIP }} SKIP" },
        { "name": "DefectDojo",      "value": "{{ $json._meta.dojoUrl || 'N/A' }}" }
      ],
      "text": "**Top hallazgos:**\n\n```\n{{ $json._meta.tablaHallazgos }}\n```"
    },
    {
      "activityTitle": "Estado por categoria",
      "text": "{{ $json._meta.resumenCategorias }}"
    }
  ],
  "potentialAction": [
    {
      "@type": "OpenUri",
      "name": "Ver en DefectDojo",
      "targets": [{ "os": "default", "uri": "{{ $json._meta.dojoUrl || 'http://localhost:8080' }}" }]
    }
  ]
}
